<script setup lang="ts">import{computed,onMounted,reactive,ref}from'vue';import{teacherAPI}from'../../api/teacher';import type{Application,Organization,Project}from'../../api/types';import{APIError}from'../../api/client';import StatusBadge from'../../components/StatusBadge.vue';import AppDialog from'../../components/AppDialog.vue';import{useToast}from'../../composables/useToast';const orgs=ref<Organization[]>([]),projects=ref<Project[]>([]),apps=ref<Application[]>([]),query=ref(''),orgFilter=ref(''),status=ref(''),drawer=ref(false),editing=ref<Project|null>(null),reviewing=ref<Application|null>(null),approve=ref(false),comment=ref(''),error=ref(''),toast=useToast(),form=reactive({organization_id:'',name:'',description:'',status:'active' as'active'|'inactive'});const filtered=computed(()=>projects.value.filter(p=>(!query.value||p.name.toLowerCase().includes(query.value.toLowerCase()))&&(!orgFilter.value||p.organization_id===orgFilter.value)&&(!status.value||p.status===status.value)));async function load(){try{[orgs.value,projects.value,apps.value]=await Promise.all([teacherAPI.organizations(),teacherAPI.projects(),teacherAPI.mentorApplications()])}catch(e){error.value=msg(e)}}function open(p?:Project){editing.value=p??null;Object.assign(form,{organization_id:p?.organization_id??'',name:p?.name??'',description:p?.description??'',status:p?.status??'active'});drawer.value=true}async function save(){try{if(editing.value)await teacherAPI.updateProject(editing.value.id,{name:form.name,description:form.description,status:form.status});else await teacherAPI.createProject(form);toast.success(editing.value?'项目已更新':'项目已创建');await load();if(!editing.value)drawer.value=false}catch(e){error.value=msg(e)}}async function toggle(p:Project){if(p.status==='active'&&!confirm('停用只影响新的申请，已有成员关系和历史记录保留。是否继续？'))return;try{await teacherAPI.updateProject(p.id,{status:p.status==='active'?'inactive':'active'});await load()}catch(e){error.value=msg(e)}}async function review(){if(!reviewing.value)return;if(!approve.value&&!comment.value.trim()){error.value='驳回必须填写原因';return}try{await teacherAPI.reviewMentor(reviewing.value.id,approve.value,comment.value||undefined);toast.success(approve.value?'导师项目申请已通过':'导师项目申请已驳回');reviewing.value=null;comment.value='';await load()}catch(e){error.value=msg(e)}}function msg(e:unknown){return e instanceof APIError?e.message:'请求失败'};onMounted(load);</script>
<template><section class="page"><div class="page-heading"><div><p class="eyebrow">TEACHER</p><h1>项目管理</h1><p class="muted">维护项目并审核导师项目申请。</p></div><button class="button primary" @click="open()">添加项目</button></div><p v-if="error" class="error banner">{{error}}</p><div class="grid two"><section class="panel"><div class="grid two"><label>搜索<input v-model="query" placeholder="项目名称"/></label><div class="row"><label>组织<select v-model="orgFilter"><option value="">全部组织</option><option v-for="o in orgs" :key="o.id" :value="o.id">{{o.name}}</option></select></label><label>状态<select v-model="status"><option value="">全部</option><option value="active">启用</option><option value="inactive">停用</option></select></label></div></div><article v-for="p in filtered" :key="p.id" class="list-row"><div><strong>{{p.name}}</strong><p class="muted">{{orgs.find(o=>o.id===p.organization_id)?.name}} · {{p.description||'暂无说明'}}</p></div><div class="actions"><StatusBadge :status="p.status"/><button class="button ghost" @click="open(p)">编辑</button><button class="button" :class="p.status==='active'?'danger':'secondary'" @click="toggle(p)">{{p.status==='active'?'停用':'启用'}}</button></div></article></section><aside class="panel"><h2>导师项目申请</h2><article v-for="app in apps" :key="app.id" class="review-row"><div><strong>{{app.mentor.name}}</strong><p class="muted">{{app.project.name}}</p></div><div class="actions"><button class="button danger" @click="reviewing=app;approve=false">驳回</button><button class="button primary" @click="reviewing=app;approve=true">通过</button></div></article><div v-if="!apps.length" class="empty">暂无待审核申请</div></aside></div><AppDialog :open="drawer" :title="editing?'编辑项目':'创建项目'" @update:open="drawer=$event"><form @submit.prevent="save"><label>所属组织<select v-model="form.organization_id" :disabled="Boolean(editing)" required><option value="">请选择</option><option v-for="o in orgs" :key="o.id" :value="o.id">{{o.name}}</option></select></label><label>名称<input v-model="form.name" required/></label><label>说明<textarea v-model="form.description" rows="4"/></label><label>状态<select v-model="form.status"><option value="active">启用</option><option value="inactive">停用</option></select></label><div class="actions"><button class="button primary">保存</button></div></form></AppDialog><AppDialog :open="Boolean(reviewing)" :title="approve?'通过导师申请':'驳回导师申请'" @update:open="reviewing=$event?reviewing:null"><p>{{reviewing?.mentor.name}} · {{reviewing?.project.name}}</p><label>审核意见<textarea v-model="comment" rows="3" :placeholder="approve?'可选':'驳回原因必填'"/></label><div class="actions"><button class="button" :class="approve?'primary':'danger'" @click="review">确认</button></div></AppDialog></section></template>
